style.css:
@-moz-document domain("roblox.com") {
/* General Background */
  body, .rbx-body, .container-main, .content {
    background-color: #e3f2fd !important; /* Light baby blue */
    color: #000 !important;
  }

  /* Headers and Nav */
  .navbar, .navigation-bar, .header, .game-name-container {
    background-color: #b3e5fc !important;
    border-bottom: 2px solid #81d4fa !important;
  }

  /* Buttons */
  button, .btn-primary, .btn-control-md, .btn-growth-md {
    background-color: #81d4fa !important;
    border: none !important;
    color: #ffffff !important;
  }

  button:hover, .btn-primary:hover, .btn-growth-md:hover {
    background-color: #4fc3f7 !important;
    color: #fff !important;
  }

  /* Cards and Game Boxes */
  .game-card, .thumbnail-2d-container, .section-content {
    background-color: #d0f0fd !important;
    border: 1px solid #b3e5fc !important;
  }

  /* Links */
  a {
    color: #1976d2 !important;
  }

  a:hover {
    color: #0d47a1 !important;
  }

  /* Text inputs / Forms */
  input, textarea, select {
    background-color: #ffffff !important;
    border: 1px solid #81d4fa !important;
    color: #000 !important;
  }

  input:focus, textarea:focus, select:focus {
    border-color: #4fc3f7 !important;
    outline: none !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 8px;
  }

  ::-webkit-scrollbar-track {
    background: #e3f2fd;
  }

  ::-webkit-scrollbar-thumb {
    background: #81d4fa;
    border-radius: 4px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: #4fc3f7;
  }
}
